import { computed, ref, type ComputedRef, type Ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { touchless_intelligence_setting } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { isUserAdmin } from 'src/utils/UserDetails';
import { useIsOrgAdmin } from 'src/utils/user-identity';
import { Acl } from 'src/core/acls/index';
import { canAccessAnalyticsRoles } from 'src/utils/analytics-access';

/**
 * Shared access gate for every Touchless Intelligence page (DOCB-14197).
 *
 * DOCB-14282 adds the ROLE dimension: it is no longer "module on AND org
 * admin" but "module on AND (org admin OR a role an admin granted the
 * Analytics Dashboard tab to)".
 *
 * NOTE — this file differs from the VESTA line ON PURPOSE. NOVA has its own
 * `TOUCHLESS_INTELLIGENCE` module toggle, which VESTA does not; VESTA's
 * Touchless rides the `ANALYTICS_DASHBOARD` flag instead. The MODULE half
 * therefore stays as it is on each line — collapsing NOVA onto the analytics
 * flag would hide Touchless from any org that has Touchless switched on and
 * the analytics dashboard switched off. The PERMISSION half is shared:
 * `canAccessAnalyticsRoles` exists precisely so both lines apply the same
 * admin-or-granted-role rule on top of their own module check.
 *
 * The naive gate — `!user_settings?.[flag] || !is_admin` evaluated once in
 * `mounted()` — is wrong on a cold load: `user_settings` is still `{}` while
 * the preferences request is in flight, so the page decides "denied", renders
 * the banner, and never re-evaluates when the flag arrives a moment later. The
 * opposite failure is just as bad: treating an unloaded `{}` as "granted" would
 * fire org-scoped API calls before anyone knows whether the org has the module.
 *
 * So the gate has three states, not two:
 *   - not ready  → render nothing, call nothing (settings still loading)
 *   - denied     → render the banner, call nothing
 *   - granted    → render the page, load data
 *
 * `accessGranted` is reactive, so a page watches it (immediate) and loads as
 * soon as it flips true. Pages ALSO re-check it inside their own `load()`:
 * a route-param watcher can re-enter a load after the flag has been revoked
 * mid-session, and defense in depth there is cheaper than an org-scoped request
 * that should never have left the browser.
 */
export interface TouchlessAccessGate {
  /** True once the preferences round has finished (successfully or not). */
  settingsReady: Ref<boolean>;
  /** The org has the module switched on. */
  flagEnabled: ComputedRef<boolean>;
  /** Reactive "current user is an organisation admin". */
  isAdmin: ComputedRef<boolean>;
  /** Settings loaded AND flag on AND admin — the only state that may fetch. */
  accessGranted: ComputedRef<boolean>;
  /** Settings loaded AND (flag off OR not admin) — show the banner. */
  accessDenied: ComputedRef<boolean>;
  /**
   * Evaluates the gate right now, re-reading the admin flag from the persisted
   * user record. Use this before firing a request; the computeds above are for
   * rendering.
   */
  checkAccess: () => boolean;
  /** Kicks off / joins the preferences fetch and resolves when it settles. */
  ensureSettingsLoaded: () => Promise<void>;
}

export function useTouchlessAccess(): TouchlessAccessGate {
  const settingStore = useSettingStore();
  const { user_settings } = storeToRefs(settingStore);

  // Settings may already be in the store from an earlier route; in that case
  // the gate is decidable immediately and must not flash a loading state.
  const settingsReady = ref(
    Object.keys(settingStore.user_settings || {}).length > 0,
  );

  const flagEnabled = computed(() =>
    toBoolPreference(user_settings.value?.[touchless_intelligence_setting]),
  );

  // The roles this org granted the Analytics Dashboard tab. Empty is the
  // meaningful default: no grants means admins only, which is also the right
  // answer while the request is still in flight.
  const allowedRoleIds = ref<string[]>([]);

  /**
   * Admin lives in LocalStorage, which Vue cannot observe. `useIsOrgAdmin()`
   * wraps it in a computed that depends on the identity version counter, so a
   * role or org change bumps the counter and every gate below re-evaluates.
   *
   * Without that dependency the rendering computeds keep serving a cached
   * grant: requests would still be blocked (`checkAccess()` is uncached), but
   * the already-loaded report would stay on screen for a user who lost access.
   */
  const isAdmin = useIsOrgAdmin();

  // These read `user_settings` DIRECTLY rather than through `flagEnabled`.
  // Vue short-circuits a computed chain when the upstream value is unchanged,
  // so depending on `flagEnabled` would skip re-evaluation — and with it the
  // admin re-read — whenever settings changed but the flag itself did not.
  // NOVA keeps its own module flag here (see the note at the top of the file);
  // only the permission half is delegated, so the two lines cannot drift on
  // who is allowed while still differing on which toggle switches the report
  // on.
  const decide = (): boolean =>
    toBoolPreference(user_settings.value?.[touchless_intelligence_setting]) &&
    canAccessAnalyticsRoles({
      isAdmin: isAdmin.value,
      userRoleIds: Acl._getUserGroupIds(),
      allowedRoleIds: allowedRoleIds.value,
    });

  const accessGranted = computed(() => settingsReady.value && decide());

  const accessDenied = computed(() => settingsReady.value && !decide());

  /** Uncached evaluation, for the moment just before a request is fired. */
  function checkAccess(): boolean {
    if (!settingsReady.value) return false;
    if (
      !toBoolPreference(
        settingStore.user_settings?.[touchless_intelligence_setting],
      )
    ) {
      return false;
    }
    return canAccessAnalyticsRoles({
      isAdmin: isUserAdmin(),
      userRoleIds: Acl._getUserGroupIds(),
      allowedRoleIds: allowedRoleIds.value,
    });
  }

  async function ensureSettingsLoaded(): Promise<void> {
    try {
      // Normally never rejects; it joins an in-flight round rather than
      // starting a second one. The role grants and the user's own roles are
      // fetched alongside so the gate is decidable in one await, and each is
      // swallowed on its own: a missing grant list denies, which is correct.
      //
      // `useAnalyticsAccess` is imported lazily because it reaches the
      // services barrel and its generated-SDK axios instance.
      await Promise.all([
        settingStore.startSettingsFetch(),
        import('src/composables/useAnalyticsAccess')
          .then(({ loadAnalyticsAccess }) => loadAnalyticsAccess())
          .then((ids) => {
            allowedRoleIds.value = ids;
          })
          .catch(() => undefined),
        Acl.fetchUserGroups().catch(() => undefined),
      ]);
    } catch {
      // Swallowed on purpose. The gate is fail-closed: an unknown module state
      // resolves to "denied", which is already the correct answer, so there is
      // nothing for a caller to handle. Propagating instead turned every
      // `void ensureSettingsLoaded()` in a lifecycle hook into an unhandled
      // rejection.
    } finally {
      settingsReady.value = true;
    }
  }

  return {
    settingsReady,
    flagEnabled,
    isAdmin,
    accessGranted,
    accessDenied,
    checkAccess,
    ensureSettingsLoaded,
  };
}
